// THE CRASH PAD: your personal pocket room. 10 table slots; tables you buy appear in their slot.
import * as THREE from '../node_modules/three/build/three.module.js';
import { toon, canvasTex, inkLine, woodTex, rnd } from '../engine/ink.js';
import { TABLES } from '../game/crafting.js';

export const CRASHPAD = { name: 'YOUR CRASH PAD', size: 26, spawn: [0, 1.7, 7.5], spawnYaw: 0 };
const W = 24, D = 18, H = 5;
// ten slots around the walls, in order, so neighbours in this list are physically next to each other
export const SLOTS = [[-9, -7.6, 0], [-4.5, -7.6, 0], [0, -7.6, 0], [4.5, -7.6, 0], [9, -7.6, 0], [10.6, -3, -Math.PI / 2], [10.6, 2, -Math.PI / 2], [6, 7.6, Math.PI], [-6, 7.6, Math.PI], [-10.6, 0, Math.PI / 2]];

function tableModel(id) {
  const g = new THREE.Group(); const T = TABLES[id];
  const wood = toon('#ffffff', { map: woodTex() }), metal = toon('#9aa0aa'), dark = toon('#2a2a30'), accent = toon(T.color);
  const add = (geo, m, x, y, z, rx = 0, ry = 0, rz = 0) => { const o = new THREE.Mesh(geo, m); o.position.set(x, y, z); o.rotation.set(rx, ry, rz); g.add(o); return o; };
  const glowM = (c, k = 2.5) => new THREE.MeshBasicMaterial({ color: new THREE.Color(c).multiplyScalar(k) });
  const bench = () => { add(new THREE.BoxGeometry(2.6, 0.15, 1.1), wood, 0, 0.95, 0); for (const [x, z] of [[-1.2, -0.45], [1.2, -0.45], [-1.2, 0.45], [1.2, 0.45]]) add(new THREE.BoxGeometry(0.12, 0.95, 0.12), wood, x, 0.47, z); };
  if (id === 'workbench') { bench(); add(new THREE.BoxGeometry(0.4, 0.25, 0.3), metal, -0.8, 1.15, 0); add(new THREE.CylinderGeometry(0.03, 0.03, 0.5, 6), wood, 0.3, 1.05, 0.2, 0, 0, Math.PI / 2); add(new THREE.BoxGeometry(2.6, 1.4, 0.05), toon('#6a5a4a'), 0, 1.75, -0.55); for (let i = 0; i < 6; i++) add(new THREE.BoxGeometry(0.05, 0.4, 0.05), metal, -1 + i * 0.4, 1.9, -0.5); }
  if (id === 'anvil') { add(new THREE.CylinderGeometry(0.35, 0.45, 0.6, 12), wood, 0, 0.3, 0); add(new THREE.BoxGeometry(0.9, 0.35, 0.35), dark, 0, 0.78, 0); add(new THREE.ConeGeometry(0.17, 0.5, 4), dark, 0.65, 0.82, 0, 0, Math.PI / 4, -Math.PI / 2); add(new THREE.BoxGeometry(1.0, 1.0, 0.8), toon('#5a4a44'), -1.4, 0.5, 0); add(new THREE.BoxGeometry(0.7, 0.5, 0.5), glowM('#ff7a1a', 1.8), -1.4, 0.75, 0.16); for (let i = 0; i < 3; i++) add(new THREE.BoxGeometry(0.05, 0.9, 0.08), metal, 1.2 + i * 0.15, 0.45, -0.3, 0.1); }
  if (id === 'armourer') { bench(); const torso = add(new THREE.CylinderGeometry(0.28, 0.22, 0.7, 12), metal, 1.6, 1.3, 0); add(new THREE.CylinderGeometry(0.03, 0.03, 0.9, 6), wood, 1.6, 0.5, 0); add(new THREE.SphereGeometry(0.2, 14, 10, 0, Math.PI * 2, 0, Math.PI / 2), metal, 1.6, 1.68, 0); add(new THREE.CylinderGeometry(0.35, 0.35, 0.05, 20), toon('#a8281e'), -0.6, 1.05, 0, Math.PI / 2 - 0.3); }
  if (id === 'boom') { bench(); for (let i = 0; i < 3; i++) { add(new THREE.BoxGeometry(0.5, 0.4, 0.4), toon('#8a3a1a'), -1.6, 0.2 + i * 0.4, 0.1 * i); } add(new THREE.SphereGeometry(0.12, 12, 10), dark, 0.2, 1.15, 0); add(new THREE.CylinderGeometry(0.01, 0.01, 0.15, 4), toon('#e8c020'), 0.2, 1.3, 0); add(new THREE.SphereGeometry(0.03, 6, 4), glowM('#ffd040', 3), 0.2, 1.38, 0); for (let i = 0; i < 4; i++) add(new THREE.CylinderGeometry(0.05, 0.05, 0.4, 8), toon('#c81a1a'), 0.7 + i * 0.12, 1.2, -0.2); add(new THREE.PlaneGeometry(1, 0.5), new THREE.MeshBasicMaterial({ map: canvasTex(256, 128, (c) => { c.fillStyle = '#f0c818'; c.fillRect(0, 0, 256, 128); c.fillStyle = '#111'; c.font = 'bold 54px sans-serif'; c.fillText('DANGER', 20, 84); }) }), 0, 1.8, -0.5); }
  if (id === 'alchemy') { bench(); const fc = ['#5ad86a', '#ff3a8a', '#3ac8ff', '#ffd020', '#b46cff']; for (let i = 0; i < 7; i++) { const c = fc[i % 5]; add(new THREE.SphereGeometry(0.1 + (i % 3) * 0.03, 12, 10), new THREE.MeshPhysicalMaterial({ color: c, transmission: 0.4, roughness: 0.05, emissive: new THREE.Color(c), emissiveIntensity: 0.8, transparent: true, opacity: 0.85 }), -1.0 + i * 0.32, 1.15, (i % 2) * 0.2 - 0.1); } add(new THREE.CylinderGeometry(0.02, 0.02, 0.6, 6), metal, 0.6, 1.3, -0.3, 0, 0, 0.6); for (let i = 0; i < 5; i++) add(new THREE.SphereGeometry(0.03, 6, 4), glowM('#9aff7a'), -0.8 + i * 0.3, 1.5 + Math.sin(i) * 0.1, 0); }
  if (id === 'stove') { add(new THREE.BoxGeometry(1.6, 0.95, 0.9), toon('#c8c8c0'), 0, 0.47, 0); add(new THREE.BoxGeometry(1.6, 0.05, 0.9), dark, 0, 0.97, 0); add(new THREE.CylinderGeometry(0.3, 0.26, 0.35, 16), metal, -0.35, 1.18, 0); add(new THREE.CircleGeometry(0.28, 16), toon('#c87a2a'), -0.35, 1.36, 0, -Math.PI / 2); add(new THREE.CylinderGeometry(0.25, 0.25, 0.04, 16), dark, 0.4, 1.0, 0); for (let i = 0; i < 4; i++) add(new THREE.ConeGeometry(0.05, 0.12, 6), glowM(i % 2 ? '#3a8aff' : '#ff7a1a'), 0.4 + Math.cos(i * 1.57) * 0.15, 1.04, Math.sin(i * 1.57) * 0.15); }
  if (id === 'tailor') { bench(); add(new THREE.BoxGeometry(0.6, 0.35, 0.3), toon('#2a2a2a'), -0.6, 1.2, 0); add(new THREE.BoxGeometry(0.15, 0.4, 0.15), toon('#2a2a2a'), -0.85, 1.35, 0); for (let i = 0; i < 4; i++) add(new THREE.CylinderGeometry(0.18, 0.18, 0.8, 16), toon(['#c86aa8', '#3a8ae8', '#e8c020', '#5ad86a'][i]), 0.4 + (i % 2) * 0.4, 1.2, -0.2 + Math.floor(i / 2) * 0.35, 0, 0, Math.PI / 2); const dummy = add(new THREE.CylinderGeometry(0.28, 0.22, 0.8, 12), toon(T.color), 1.7, 1.3, 0); add(new THREE.CylinderGeometry(0.03, 0.03, 0.9, 6), wood, 1.7, 0.45, 0); }
  if (id === 'tinker') { bench(); for (let i = 0; i < 4; i++) { const gr = new THREE.Mesh(new THREE.TorusGeometry(0.12 + i * 0.04, 0.025, 6, 12), toon('#c8a040')); gr.position.set(-0.9 + i * 0.35, 1.1, 0); gr.rotation.x = Math.PI / 2; g.add(gr); } add(new THREE.BoxGeometry(0.4, 0.3, 0.3), toon('#3a3a40'), 0.8, 1.17, 0); add(new THREE.SphereGeometry(0.06, 8, 6), glowM('#3ac8ff', 3), 0.8, 1.38, 0.1); add(new THREE.CylinderGeometry(0.02, 0.02, 0.8, 6), metal, 1.15, 1.4, 0, 0, 0, -0.5); add(new THREE.SphereGeometry(0.08, 10, 8), glowM('#ffe8a0'), 1.35, 1.75, 0); }
  if (id === 'jeweller') { add(new THREE.BoxGeometry(1.4, 0.95, 0.8), wood, 0, 0.47, 0); add(new THREE.CylinderGeometry(0.02, 0.02, 0.5, 6), metal, 0.3, 1.2, 0); add(new THREE.TorusGeometry(0.15, 0.02, 8, 20), metal, 0.3, 1.45, 0.05); add(new THREE.CircleGeometry(0.14, 20), new THREE.MeshPhysicalMaterial({ color: '#c8e8ff', transmission: 0.8, transparent: true, opacity: 0.4 }), 0.3, 1.45, 0.06); for (let i = 0; i < 5; i++) add(new THREE.OctahedronGeometry(0.04, 0), new THREE.MeshPhysicalMaterial({ color: ['#e83a5a', '#3ac8ff', '#5ad86a', '#ffd020', '#b46cff'][i], roughness: 0.05, clearcoat: 1, emissive: new THREE.Color(['#e83a5a', '#3ac8ff', '#5ad86a', '#ffd020', '#b46cff'][i]), emissiveIntensity: 0.4 }), -0.5 + i * 0.15, 1.0, 0.1); }
  if (id === 'font') { add(new THREE.CylinderGeometry(0.45, 0.6, 0.9, 16), toon('#8a8090'), 0, 0.45, 0); add(new THREE.CylinderGeometry(0.75, 0.55, 0.3, 24), toon('#8a8090'), 0, 1.05, 0); add(new THREE.CircleGeometry(0.68, 24), new THREE.MeshPhysicalMaterial({ color: '#b46cff', emissive: new THREE.Color('#7a3aff'), emissiveIntensity: 1.2, roughness: 0.05, clearcoat: 1 }), 0, 1.21, 0, -Math.PI / 2); for (let i = 0; i < 8; i++) add(new THREE.SphereGeometry(0.03, 6, 4), glowM('#d8a8ff', 3), Math.cos(i) * 0.5, 1.5 + (i % 3) * 0.25, Math.sin(i) * 0.5); }
  if (id === 'still') { add(new THREE.SphereGeometry(0.45, 18, 14), toon('#c87a3a'), -0.4, 0.6, 0); add(new THREE.CylinderGeometry(0.06, 0.06, 0.7, 8), toon('#c87a3a'), -0.4, 1.3, 0); add(new THREE.TorusGeometry(0.2, 0.04, 8, 20), toon('#c87a3a'), 0.25, 0.9, 0); add(new THREE.TorusGeometry(0.2, 0.04, 8, 20), toon('#c87a3a'), 0.25, 0.75, 0); add(new THREE.CylinderGeometry(0.2, 0.2, 0.4, 14), new THREE.MeshPhysicalMaterial({ color: '#c8ecff', transmission: 0.8, transparent: true, opacity: 0.5 }), 0.7, 0.2, 0); }
  if (id === 'scribe') { add(new THREE.BoxGeometry(1.6, 0.1, 0.9), wood, 0, 0.95, 0, -0.15); for (const [x, z] of [[-0.7, -0.35], [0.7, -0.35], [-0.7, 0.35], [0.7, 0.35]]) add(new THREE.BoxGeometry(0.08, 0.95, 0.08), wood, x, 0.47, z); add(new THREE.PlaneGeometry(0.6, 0.4), toon('#ece2c8'), 0, 1.02, 0, -Math.PI / 2 - 0.15); add(new THREE.CylinderGeometry(0.004, 0.004, 0.3, 4), toon('#f0f0f0'), 0.4, 1.12, 0.1, 0.5); add(new THREE.CylinderGeometry(0.05, 0.05, 0.08, 10), toon('#141418'), 0.55, 1.02, -0.2); for (let i = 0; i < 6; i++) add(new THREE.BoxGeometry(0.1, 0.3, 0.22), toon(['#5a1a14', '#1a3a2a', '#1a2a5a'][i % 3]), -0.6 + i * 0.11, 1.15, -0.3); }
  const light = new THREE.PointLight(T.color, 3, 4); light.position.set(0, 2.2, 1.2); g.add(light);
  const sign = new THREE.Mesh(new THREE.PlaneGeometry(2.4, 0.45), new THREE.MeshBasicMaterial({ map: canvasTex(512, 96, (c) => { c.fillStyle = '#16121e'; c.fillRect(0, 0, 512, 96); c.fillStyle = T.color; c.font = 'bold 46px sans-serif'; c.textAlign = 'center'; c.fillText(T.name.toUpperCase(), 256, 64); c.strokeStyle = T.color; c.lineWidth = 6; c.strokeRect(3, 3, 506, 90); }) }));
  sign.position.set(0, 2.9, -0.3); g.add(sign);
  return g;
}

export function buildCrashPad(ink, col, onProgress = () => {}, state) {
  const { scene, fx } = ink;
  scene.background = new THREE.Color('#1a1420'); scene.fog = new THREE.Fog('#1a1420', 30, 60);
  const floorTex = canvasTex(512, 512, (g, w, h) => { const n = 6, s = w / n; for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) { g.fillStyle = `hsl(28,${30 + rnd() * 10}%,${30 + rnd() * 8}%)`; g.fillRect(i * s, j * s, s, s); } g.strokeStyle = '#0d0b12'; for (let i = 0; i <= n; i++) { inkLine(g, i * s, 0, i * s, h, 4); inkLine(g, 0, i * s, w, i * s, 4); } }, [4, 3]);
  const fl = new THREE.Mesh(new THREE.PlaneGeometry(W, D), toon('#ffffff', { map: floorTex })); fl.rotation.x = -Math.PI / 2; scene.add(fl);
  const rug = new THREE.Mesh(new THREE.CircleGeometry(4, 40), toon('#7a2a3a')); rug.rotation.x = -Math.PI / 2; rug.position.y = 0.01; scene.add(rug);
  const wallTex = canvasTex(512, 256, (g, w, h) => { g.fillStyle = '#4a3a5a'; g.fillRect(0, 0, w, h); for (let i = 0; i < 16; i++) { g.fillStyle = i % 2 ? '#52425e' : '#463654'; g.fillRect(i * 32, 0, 32, h); } g.fillStyle = '#2a2034'; g.fillRect(0, h * 0.7, w, h * 0.3); g.strokeStyle = '#0d0b12'; inkLine(g, 0, h * 0.7, w, h * 0.7, 5); }, [4, 1]);
  for (const [x, z, ry, len] of [[0, -D / 2, 0, W], [0, D / 2, Math.PI, W], [-W / 2, 0, Math.PI / 2, D], [W / 2, 0, -Math.PI / 2, D]]) { const w = new THREE.Mesh(new THREE.PlaneGeometry(len, H), toon('#ffffff', { map: wallTex })); w.position.set(x, H / 2, z); w.rotation.y = ry; scene.add(w); }
  const ceil = new THREE.Mesh(new THREE.PlaneGeometry(W, D), toon('#2a2232')); ceil.rotation.x = Math.PI / 2; ceil.position.y = H; scene.add(ceil);
  col.box(0, -D / 2 - 0.5, W / 2, 0.5); col.box(0, D / 2 + 0.5, W / 2, 0.5); col.box(-W / 2 - 0.5, 0, 0.5, D / 2); col.box(W / 2 + 0.5, 0, 0.5, D / 2);
  scene.add(new THREE.HemisphereLight('#ffe0c0', '#3a2a40', 1.3));
  for (const [x, z] of [[-6, -3], [6, -3], [0, 4]]) { const l = new THREE.PointLight('#ffd8a0', 12, 16, 1.4); l.position.set(x, H - 0.5, z); scene.add(l); const b = new THREE.Mesh(new THREE.SphereGeometry(0.2, 10, 8), new THREE.MeshBasicMaterial({ color: new THREE.Color('#ffe8c0').multiplyScalar(2.5) })); b.position.set(x, H - 0.4, z); scene.add(b); fx.push(b); }
  // the door back to the floor, a couch, a TV that only shows you
  const door = new THREE.Mesh(new THREE.BoxGeometry(1.6, 2.6, 0.2), toon('#6a4a2a')); door.position.set(0, 1.3, D / 2 - 0.1); scene.add(door);
  const exitS = new THREE.Mesh(new THREE.PlaneGeometry(1.4, 0.4), new THREE.MeshBasicMaterial({ map: canvasTex(256, 72, (c) => { c.fillStyle = '#0a3a12'; c.fillRect(0, 0, 256, 72); c.fillStyle = '#5aff7a'; c.font = 'bold 40px sans-serif'; c.fillText('EXIT [H]', 30, 52); }) })); exitS.position.set(0, 2.9, D / 2 - 0.12); exitS.rotation.y = Math.PI; scene.add(exitS);
  const couch = new THREE.Group(); couch.add(Object.assign(new THREE.Mesh(new THREE.BoxGeometry(3, 0.5, 1.1), toon('#3a5a7a')))); couch.children[0].position.y = 0.45; const back = new THREE.Mesh(new THREE.BoxGeometry(3, 0.8, 0.3), toon('#3a5a7a')); back.position.set(0, 0.9, -0.45); couch.add(back); couch.position.set(-3, 0, 2.2); couch.rotation.y = Math.PI; scene.add(couch); col.box(-3, 2.2, 1.5, 0.6);
  const tv = new THREE.Mesh(new THREE.PlaneGeometry(2.2, 1.3), new THREE.MeshBasicMaterial({ map: canvasTex(256, 150, (c) => { c.fillStyle = '#102030'; c.fillRect(0, 0, 256, 150); c.fillStyle = '#E5484D'; c.fillRect(8, 8, 50, 18); c.fillStyle = '#fff'; c.font = 'bold 14px sans-serif'; c.fillText('LIVE', 16, 22); c.fillStyle = '#F5C518'; c.font = 'bold 22px sans-serif'; c.fillText('YOU, ON TV', 60, 90); }), color: new THREE.Color(1.4, 1.4, 1.4) })); tv.position.set(-3, 1.6, -0.3); scene.add(tv);
  // table slots
  const slotGroups = SLOTS.map(([x, z, ry], i) => { const g = new THREE.Group(); g.position.set(x, 0, z); g.rotation.y = ry; scene.add(g); return g; });
  const forSale = (i) => { const g = new THREE.Group(); const ring = new THREE.Mesh(new THREE.RingGeometry(1.0, 1.15, 32), new THREE.MeshBasicMaterial({ color: '#F5C518', transparent: true, opacity: 0.6, side: THREE.DoubleSide })); ring.rotation.x = -Math.PI / 2; ring.position.y = 0.02; g.add(ring); fx.push(ring); const s = new THREE.Mesh(new THREE.PlaneGeometry(1.8, 0.5), new THREE.MeshBasicMaterial({ map: canvasTex(256, 72, (c) => { c.fillStyle = '#16121e'; c.fillRect(0, 0, 256, 72); c.fillStyle = '#F5C518'; c.font = 'bold 30px sans-serif'; c.textAlign = 'center'; c.fillText(`EMPTY SLOT ${i + 1}`, 128, 46); }), transparent: true, opacity: 0.85 })); s.position.set(0, 1.4, 0); g.add(s); return g; };
  function refreshTables(S) {
    slotGroups.forEach((sg, i) => { sg.clear(); const id = Object.keys(S.tables).find((k) => S.tables[k].slot === i); sg.add(id ? tableModel(id) : forSale(i)); });
  }
  SLOTS.forEach(([x, z]) => col.circle(x, z, 1.1));
  refreshTables(state); onProgress(1);
  const map = { pillars: [], cars: [], water: [], pois: [{ name: 'Your Crash Pad', x: 0, z: 0, r: 30, kind: 'hub', safe: true }] };
  return { map, mobs: [], tick: () => {}, size: 26, ceiling: H, refreshTables, slots: SLOTS };
}
